    <details class="finance-more"><summary>Más herramientas de tesorería</summary><div class="finance-tools"><a class="btn small" href="/api/finance/reports.csv?${financeQuery()}">Descargar CSV</a><a class="btn small" href="/api/finance/reports.pdf?${financeQuery()}">Descargar PDF</a><button class="btn small" id="finance-distribution">Distribución</button><button class="btn small" id="finance-dist-settings">Porcentajes</button><button class="btn small" id="finance-dist-history">Historial</button><button class="btn small" id="finance-projection">Simular</button><button class="btn small" id="finance-alerts">Alertas</button><button class="btn small" id="finance-alert-settings">Configurar alertas</button><button class="btn small" id="finance-objectives">Objetivos</button></div></details>
