 for(const id of ['finance-from','finance-to'])document.querySelector('#'+id)?.addEventListener('change',e=>{if(id==='finance-from')financeFrom=e.target.value;else financeTo=e.target.value;if(financeFrom&&financeTo&&financeFrom<=financeTo)renderFinance();});
