function openReconcileMovement(id,accounts){modal('Conciliar movimiento','<div class="field"><label>Cuenta</label><select name="account_id" required>'+accounts.map(a=>`<option value="${esc(a.id)}">${esc(a.name)}</option>`).join('')+'</select></div><div class="field"><label>Referencia bancaria o nota</label><input name="reference" required maxlength=160></div>',{submitLabel:'Conciliar',onSubmit:async f=>{const {error}=await sb.request(`/api/finance/movements/${encodeURIComponent(id)}/reconcile`,{method:'PATCH',body:JSON.stringify(Object.fromEntries(f))});if(error)throw error;notify('Movimiento conciliado.');renderFinance();}});}
function openMaintenanceForm(){const clients=platformData.clients.map(c=>`<option value="${esc(c.id)}">${esc(c.display_name)}</option>`).join('');modal('Nuevo mantenimiento mensual',`<div class="field"><label>Cliente</label><select name="client_id" required><option value="">Selecciona cliente</option>${clients}</select></div><div class="field"><label>Servicio</label><input name="service_name" required maxlength="160" value="Mantenimiento web"></div><div class="form-grid"><div class="field"><label>Tarifa mensual (USD)</label><input name="monthly_fee" type="number" min="0.01" step="0.01" required></div><div class="field"><label>Fecha de inicio</label><input name="started_at" type="date" value="${new Intl.DateTimeFormat('en-CA',{timeZone:'America/Guayaquil'}).format(new Date())}" required></div></div><div class="field"><label>Próximo vencimiento</label><input name="next_due_at" type="date" required></div><div class="field"><label>Proyecto relacionado (opcional)</label><select name="project_id"><option value="">Sin proyecto relacionado</option>${platformData.projects.map(p=>`<option value="${esc(p.id)}">${esc(p.project_name||p.company_name)}</option>`).join('')}</select></div><div class="field"><label>Notas</label><textarea name="notes" maxlength="1000"></textarea></div>`,{submitLabel:'Crear mantenimiento',onSubmit:async f=>{const body=Object.fromEntries(f);const {error}=await sb.request('/api/finance/maintenance',{method:'POST',body:JSON.stringify(body)});if(error)throw error;notify('Mantenimiento mensual creado.');renderFinance();}});}
function openMaintenanceInvoice(id){const today=new Intl.DateTimeFormat('en-CA',{timeZone:'America/Guayaquil'}).format(new Date());modal('Crear factura mensual','<div class="field"><label>Período</label><input name="period" type="month" required></div><div class="field"><label>Fecha de vencimiento (opcional)</label><input name="due_at" type="date"></div><p class="subtext">La tarifa se toma del contrato. Solo se permite una factura por período.</p>',{submitLabel:'Crear factura',onSubmit:async f=>{const body=Object.fromEntries(f);if(!body.due_at)delete body.due_at;const {error}=await sb.request(`/api/finance/maintenance/${encodeURIComponent(id)}/invoices`,{method:'POST',body:JSON.stringify(body)});if(error)throw error;notify('Factura mensual creada.');renderFinance();}});document.querySelector('[name="period"]').value=today.slice(0,7);}
function openMaintenancePayment(id,balance){modal('Registrar abono de mantenimiento',`<p class="notice">Saldo pendiente: ${money(balance/100)}</p><div class="field"><label>Abono (USD)</label><input name="amount" type="number" min="0.01" step="0.01" max="${(balance/100).toFixed(2)}" required></div><div class="field"><label>Fecha de cobro</label><input name="paid_at" type="date" value="${new Intl.DateTimeFormat('en-CA',{timeZone:'America/Guayaquil'}).format(new Date())}" required></div><div class="field"><label>Método</label><input name="payment_method" maxlength="80"></div><div class="field"><label>Referencia</label><input name="reference" maxlength="160"></div>`,{submitLabel:'Guardar abono',onSubmit:async f=>{const body=Object.fromEntries(f);body.request_key=crypto.randomUUID();const {error}=await sb.request(`/api/finance/maintenance/invoices/${encodeURIComponent(id)}/payments`,{method:'POST',body:JSON.stringify(body)});if(error)throw error;notify('Cobro de mantenimiento registrado.');renderFinance();}});}
function openExpenseForm(){const projects=platformData.projects.map(p=>`<option value="${esc(p.id)}">${esc(p.project_name||p.company_name)}</option>`).join('');modal('Registrar gasto',`<div class="field"><label>Nombre</label><input name="name" required maxlength="160" placeholder="Ej. Suscripción de software"></div><div class="form-grid"><div class="field"><label>Categoría</label><select name="category">${Object.entries(expenseCategoryLabels).map(([key,label])=>`<option value="${key}">${label}</option>`).join('')}</select></div><div class="field"><label>Importe (USD)</label><input name="amount" type="number" min="0.01" step="0.01" required></div></div><div class="form-grid"><div class="field"><label>Fecha del gasto</label><input name="incurred_at" type="date" value="${new Intl.DateTimeFormat('en-CA',{timeZone:'America/Guayaquil'}).format(new Date())}" required></div><div class="field"><label>Fecha de vencimiento (opcional)</label><input name="due_at" type="date"></div><div class="field"><label>Frecuencia</label><select name="frequency"><option value="once">Único</option><option value="monthly">Mensual</option><option value="yearly">Anual</option></select></div></div><div class="field"><label>Proveedor</label><input name="vendor" maxlength="160"></div><div class="field"><label>Proyecto relacionado</label><select name="project_id"><option value="">Gasto general</option>${projects}</select></div><div class="field"><label>Estado</label><select name="status"><option value="pending">Pendiente</option><option value="paid">Ya pagado</option></select></div><div class="form-grid"><div class="field"><label>Método de pago (si pagado)</label><input name="payment_method" maxlength="80"></div><div class="field"><label>Referencia</label><input name="reference" maxlength="160"></div></div><div class="field"><label>Comprobante (enlace opcional)</label><input name="receipt_url" type="url" maxlength="500"></div><div class="field"><label>Notas</label><textarea name="notes" maxlength="1000"></textarea></div>`,{submitLabel:'Guardar gasto',onSubmit:async f=>{const body=Object.fromEntries(f);body.request_key=crypto.randomUUID();const {error}=await sb.request('/api/finance/expenses',{method:'POST',body:JSON.stringify(body)});if(error)throw error;notify('Gasto registrado.');renderFinance();}});}
function wireCommon(){document.querySelectorAll('[data-open]').forEach(el=>{if(el.tagName!=='BUTTON'){el.tabIndex=0;el.setAttribute('role','button');el.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();el.click();}};}});document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>{page=b.dataset.page;renderShell()});const s=document.querySelector('#search');if(s)s.oninput=()=>{query=s.value;const pos=s.selectionStart;renderPage();const n=document.querySelector('#search');n.focus();n.setSelectionRange(pos,pos)};for(const [id,key] of [['filter-stage','stage'],['filter-owner','owner'],['filter-source','source'],['filter-service','service'],['filter-followup','followup'],['filter-after','after'],['filter-before','before']])document.querySelector('#'+id)?.addEventListener('change',e=>{filters[key]=e.target.value;renderPage()});}
function modal(title,body,{wide=false,submitLabel='Guardar',onSubmit}={}){const root=document.querySelector('#modal-root');root.innerHTML=`<div class="modal-backdrop"><section role="dialog" aria-modal="true" aria-labelledby="modal-heading" class="modal ${wide?'wide':''}"><header class="modal-head"><h2 id="modal-heading">${title}</h2><button class="icon-btn" type="button" aria-label="Cerrar" data-close>✕</button></header><form id="modal-form"><div class="modal-body">${body}</div><footer class="modal-foot"><button class="btn" type="button" data-close>Cancelar</button>${onSubmit?`<button class="btn primary" type="submit" id="modal-submit">${submitLabel}</button>`:''}</footer></form></section></div>`;root.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>root.innerHTML='');root.querySelector('.modal-backdrop').onclick=e=>{if(e.target.classList.contains('modal-backdrop'))root.innerHTML=''};for(const button of root.querySelectorAll('button:not([type])'))button.type='button';const form=root.querySelector('#modal-form');if(!onSubmit)form.onsubmit=e=>e.preventDefault();if(onSubmit)form.onsubmit=async e=>{e.preventDefault();const b=root.querySelector('#modal-submit');b.disabled=true;b.textContent='Guardando…';try{await onSubmit(new FormData(form));if(root.contains(form))root.innerHTML=''}catch(err){notify(errText(err),true);b.disabled=false;b.textContent=submitLabel}};root.onkeydown=e=>{if(e.key==='Escape'){root.innerHTML='';return;}if(e.key==='Tab'){const controls=[...root.querySelectorAll('button,input,select,textarea,summary')].filter(x=>!x.disabled&&x.getClientRects().length);const first=controls[0],last=controls.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}};root.querySelector('input,select,textarea,button')?.focus();return root;}
function optionsServices(selected=''){return `<option value="">Sin especificar</option>${services.filter(s=>s.is_active||s.id===selected).map(s=>`<option value="${s.id}" ${s.id===selected?'selected':''}>${esc(s.name)}</option>`).join('')}`}
function openLeadForm(){
 let weakConfirmed=false;
 const root=modal('Nueva oportunidad',`<p class="subtext">Registra lo esencial. Puedes completar los detalles después.</p><div id="duplicate-result"></div><div class="form-grid"><div class="field"><label>Empresa</label><input name="company_name" required minlength="2" maxlength="160" autocomplete="organization"></div><div class="field"><label>Contacto</label><input name="contact_name" required minlength="2" maxlength="160" autocomplete="name"></div><div class="field"><label>Teléfono</label><input name="phone" inputmode="tel" maxlength="40" autocomplete="tel"></div><div class="field"><label>Email</label><input name="email" type="email" autocomplete="email"></div><div class="field"><label>Servicio</label><select name="service_id">${optionsServices()}</select></div><div class="field"><label>Precio estimado (USD)</label><input name="estimated_value" type="number" min="0" step="0.01" value="0"></div><div class="field"><label>Fuente</label><select name="source">${sources.map(x=>`<option>${esc(x)}</option>`).join('')}</select></div>${isAdmin()?`<div class="field"><label>Propietario</label><select name="owner_id"><option value="${profile.id}">Yo (${esc(profile.full_name)})</option>${profiles.filter(p=>p.role==='executive'&&p.is_active).map(p=>`<option value="${p.id}">${esc(p.full_name)}</option>`).join('')}</select></div>`:''}<div class="field"><label>Próximo seguimiento (Ecuador)</label><input name="followup_at" type="datetime-local"></div><div class="field"><label>Próxima acción</label><input name="followup_description" maxlength="1000" placeholder="Ej. Llamar al contacto"></div></div><details><summary>Más información</summary><div class="form-grid"><div class="field"><label>Web</label><input name="website" maxlength="160" placeholder="empresa.com"></div><div class="field"><label>Cargo</label><input name="job_title" maxlength="160"></div><div class="field"><label>Ciudad</label><input name="city" maxlength="160"></div><div class="field"><label>Origen</label><select name="lead_origin"><option value="self_generated">Prospección propia</option><option value="company_assigned">Asignado por NextWebEC</option><option value="referral">Referido</option><option value="other">Otro</option></select></div><div class="field span-2"><label>Notas</label><textarea name="notes" maxlength="4000"></textarea></div></div></details>`,{submitLabel:'Crear oportunidad',onSubmit:async f=>{
 const {data,error}=await sb.rpc('create_lead_if_unique',{p_company:String(f.get('company_name')).trim(),p_contact:String(f.get('contact_name')).trim(),p_phone:f.get('phone')||null,p_email:f.get('email')||null,p_website:f.get('website')||null,p_service_id:f.get('service_id')||null,p_estimated_value:Number(f.get('estimated_value')||0),p_source:f.get('source'),p_lead_origin:f.get('lead_origin')||'self_generated',p_notes:f.get('notes')||null,p_job_title:f.get('job_title')||null,p_city:f.get('city')||null,p_owner_id:isAdmin()?f.get('owner_id'):null,p_followup_at:fromEcuadorInput(f.get('followup_at')),p_followup_description:f.get('followup_description')||null,p_confirm_weak:weakConfirmed});if(error)throw error;
 const result=data[0];if(!result.created){const box=root.querySelector('#duplicate-result');box.innerHTML=`<div class="alert"><b>Posible oportunidad existente</b><p>${esc(result.company_name)} · ${esc(result.owner_name)} · ${date(result.created_at)} · ${esc(labelStage(result.status))}</p>${result.can_open?'<button class="btn small" type="button" id="review-existing">Revisar oportunidad</button>':'<span>Consulta con el responsable para revisar el registro.</span>'}${result.match_reason==='company'?'<button class="btn small" type="button" id="allow-weak">Es otro contacto: continuar</button>':''}</div>`;box.querySelector('#review-existing')?.addEventListener('click',()=>openDetail(result.lead_id));box.querySelector('#allow-weak')?.addEventListener('click',()=>{weakConfirmed=true;root.querySelector('#modal-form').requestSubmit();});throw new Error(result.match_reason==='company'?'Revisa la coincidencia de empresa antes de continuar.':'El teléfono, email o dominio ya está registrado.');}
 await loadApp();notify('Oportunidad creada.');queueMicrotask(()=>openDetail(result.lead_id));
 }});
 root.querySelector('[name="service_id"]').onchange=e=>{const service=services.find(s=>s.id===e.target.value);const input=root.querySelector('[name="estimated_value"]');if(service)input.value=service.default_price;};
 for(const input of root.querySelectorAll('[name="company_name"],[name="contact_name"],[name="phone"],[name="email"],[name="website"]'))input.addEventListener('input',()=>{weakConfirmed=false;root.querySelector('#duplicate-result').innerHTML='';});
}
function renderHistory(hist) {
  if (!hist.length) return '<div class="empty">Aún no hay cambios registrados.</div>';
  const fields = [['status','Estado'],['estimated_value','Precio estimado'],['total_value','Valor final'],['owner_id','Responsable'],['company_name','Empresa'],['contact_name','Contacto'],['phone','Teléfono'],['email','Email'],['website','Sitio web'],['job_title','Cargo'],['city','Ciudad'],['country','País'],['service_id','Servicio'],['source','Fuente'],['lead_origin','Origen'],['next_action','Próxima acción'],['next_action_at','Seguimiento'],['notes','Notas'],['deleted_at','Archivo']];
  const value = (key, v) => v == null || v === '' ? '—' : key === 'status' ? labelStage(v) : key === 'owner_id' ? person(v) : key === 'service_id' ? (services.find(s => s.id === v)?.name || 'Sin especificar') : ['estimated_value','total_value'].includes(key) ? money(v) : key === 'next_action_at' ? dt(v) : key === 'deleted_at' ? dt(v) : String(v);
  const item = h => {
    if(h.after_data?.followup_id){const old=h.before_data||{},next=h.after_data;const title=old.status===null?'Seguimiento creado':next.status==='completed'?'Seguimiento completado':next.status==='cancelled'?'Seguimiento cancelado':'Seguimiento actualizado';const details=[['description','Acción'],['type','Tipo'],['due_at','Fecha']].filter(([key])=>old[key]!==next[key]);const val=(key,v)=>key==='due_at'?dt(v):key==='type'?(followupTypes.find(x=>x[0]===v)?.[1]||'—'):v||'—';return `<div class="timeline-item"><b>${title}</b><p>${esc(person(h.actor_id))} · <time>${dt(h.created_at)}</time></p><details class="history-details"><summary>Ver cambios</summary><ul>${details.map(([key,label])=>`<li><strong>${label}</strong>: ${esc(val(key,old[key]))} → ${esc(val(key,next[key]))}</li>`).join('')}</ul></details></div>`;}
    const old = h.before_data || {}, next = h.after_data || {};
    const changed = fields.filter(([key]) => old[key] !== next[key]);
    let title = h.after_data?.payment_id ? (h.after_data.status==='confirmed'?'Cobro confirmado':'Cobro cancelado') : 'Datos actualizados';
    if (h.operation === 'INSERT') title = 'Oportunidad creada';
    else if (!h.after_data?.payment_id && changed.length === 1) {
      const [key, label] = changed[0];
      title = key === 'status' ? `${labelStage(old.status)} → ${labelStage(next.status)}` : key === 'owner_id' ? `Responsable: ${person(next.owner_id)}` : key === 'deleted_at' ? (next.deleted_at ? 'Oportunidad archivada' : 'Oportunidad restaurada') : `${label} actualizado`;
    } else if (!h.after_data?.payment_id && changed.length > 1) title = `${changed.length} datos actualizados`;
    const details = h.operation !== 'INSERT' && changed.length ? `<details class="history-details"><summary>Ver cambios</summary><ul>${changed.map(([key,label]) => `<li><strong>${esc(label)}</strong>: ${esc(value(key,old[key]))} → ${esc(value(key,next[key]))}</li>`).join('')}</ul></details>` : '';
    return `<div class="timeline-item"><b>${esc(title)}</b><p>${esc(person(h.actor_id))} · <time>${dt(h.created_at)}</time></p>${details}</div>`;
  };
  return `<div class="timeline">${hist.slice(0,5).map(item).join('')}</div>${hist.length > 5 ? `<details class="history-more"><summary>Ver ${hist.length - 5} cambios anteriores</summary><div class="timeline">${hist.slice(5).map(item).join('')}</div></details>` : ''}`;
}

async function openDetail(id){
 const lead=leads.find(l=>l.id===id)||(isAdmin()?archivedLeads.find(l=>l.id===id):null);if(!lead)return;
 const [ar,hr]=await Promise.all([sb.from('activities').select('*').eq('lead_id',id).order('occurred_at',{ascending:false}).limit(40),sb.from('lead_audit_log').select('*').eq('lead_id',id).order('created_at',{ascending:false}).limit(40)]);
 if(ar.error||hr.error){notify(errText(ar.error||hr.error),true);return;}
 const sale=sales.find(s=>s.lead_id===id),tasks=followups.filter(f=>f.lead_id===id&&f.status==='pending'),readOnly=Boolean(lead.deleted_at);
 const facts=[['Contacto',lead.contact_name],['Cargo',lead.job_title],['Teléfono',lead.phone],['Email',lead.email],['Web',lead.website],['Servicio',lead.services?.name],['Fuente',lead.source],['Precio estimado',money(lead.estimated_value)],['Responsable',person(lead.owner_id)],['Registrado por',person(lead.created_by)],['Fecha de creación',dt(lead.created_at)],['Última actividad',dt(lead.last_contact_at)],['Próxima acción',tasks[0]?.description],['Próximo seguimiento',dt(tasks[0]?.due_at)]];
 const root=modal(esc(lead.company_name),`<div class="detail-grid"><div>${readOnly?'<div class="notice">Esta oportunidad está archivada. Puedes consultar su historial o restaurarla.</div>':''}${sale&&!readOnly?'<div class="notice">Esta oportunidad tiene una venta registrada. Para cambiarla de etapa, administración debe reabrir la venta.</div>':''}<div class="field"><label for="detail-stage">Estado de oportunidad</label><select id="detail-stage" ${readOnly||sale?'disabled':''}>${stages.map(([key,label])=>`<option value="${key}" ${key===lead.status?'selected':''}>${label}</option>`).join('')}</select></div><div class="quick-actions">${!readOnly?`${contactLinks(lead)}<button class="btn small" id="edit-lead">Editar datos</button><button class="btn small" id="edit-price">Editar precio estimado</button>${activityTypes.map(([key,label])=>`<button class="btn small" data-activity="${key}">${label}</button>`).join('')}${lead.status!=='lost'?`${tasks.length?'<button class="btn small" id="edit-next-followup">Editar próximo seguimiento</button>':''}<button class="btn primary small" id="add-followup">＋ Seguimiento</button>`:''}${lead.status==='won'&&!sale?'<button class="btn primary small" id="close-value">Registrar valor final</button>':''}`:''}</div><div class="detail-facts">${facts.map(([label,value])=>`<div class="fact"><label>${label}</label><b>${esc(value||'—')}</b></div>`).join('')}</div>${lead.notes?`<p class="detail-notes">${esc(lead.notes)}</p>`:''}${isAdmin()&&!readOnly?`<details class="detail-options"><summary>Administrar oportunidad</summary><div class="field"><label>Reasignar responsable</label><select id="reassign">${profiles.filter(p=>p.is_active).map(p=>`<option value="${p.id}" ${p.id===lead.owner_id?'selected':''}>${esc(p.full_name)}</option>`).join('')}</select></div><button class="btn danger small" id="archive-lead">Archivar oportunidad</button></details>`:''}${readOnly?'<button class="btn primary" id="restore-lead">Restaurar oportunidad</button>':''}${sale?`<section class="panel finance-panel"><div class="panel-head"><h2>Venta y cobros</h2><div class="table-actions">${isAdmin()&&!readOnly?'<button class="btn small" id="edit-final-price">Editar valor final</button><button class="btn danger small" id="reopen-sale">Reabrir venta</button>':''}${isAdmin()&&!readOnly&&sale.pending_balance>0?'<button class="btn small" id="add-payment">＋ Cobro</button>':''}</div></div><div class="detail-facts">${[['Valor final',sale.total_value],['Cobrado',sale.collected_amount],['Saldo pendiente',sale.pending_balance]].map(([label,value])=>`<div class="fact"><label>${label}</label><b>${money(value)}</b></div>`).join('')}</div>${payments.filter(p=>p.sale_id===sale.id).map(p=>`<div class="payment-row"><span>${date(p.paid_at)} · ${esc(p.payment_method||'Pago')}<small>${p.status==='confirmed'?'Confirmado':p.status==='pending'?'Pendiente':'Cancelado'}${p.reference?' · '+esc(p.reference):''}</small></span><b>${money(p.amount)}</b>${isAdmin()&&p.status!=='cancelled'?`<div>${p.status==='pending'?`<button class="btn small" data-payment="${p.id}" data-status="confirmed">Confirmar</button>`:''}<button class="btn danger small" data-payment="${p.id}" data-status="cancelled">Anular</button></div>`:''}</div>`).join('')}</section>`:''}</div><div><section class="panel"><div class="panel-head"><h2>Seguimientos pendientes</h2></div>${tasks.map(taskRow).join('')||'<div class="empty"><strong>Todo al día.</strong>No hay seguimientos pendientes.</div>'}</section><section class="panel finance-panel"><div class="panel-head"><h2>Actividad comercial</h2></div>${ar.data.length?`<div class="timeline">${ar.data.filter(a=>a.type!=='task'&&a.type!=='commission').map(a=>`<div class="timeline-item"><b>${esc(activityLabel(a.type))} · ${esc(person(a.created_by))}</b><p>${esc(a.subject)}${a.body?`<br>${esc(a.body)}`:''}</p><time>${dt(a.occurred_at)}</time></div>`).join('')}</div>`:'<div class="empty">Registra una llamada, mensaje o nota para empezar.</div>'}</section><section class="panel finance-panel"><div class="panel-head"><h2>Historial del sistema</h2></div>${renderHistory(hr.data)}</section></div></div>`,{wide:true});
 root.querySelector('#restore-lead')?.addEventListener('click',()=>restoreLead(lead));if(readOnly)return;
 root.querySelector('#detail-stage').onchange=e=>changeStage(lead,e.target.value);
 root.querySelector('#edit-lead').onclick=()=>openEditLead(lead);
 root.querySelector('#edit-price').onclick=()=>openPriceEditor(lead);
 root.querySelector('#edit-final-price')?.addEventListener('click',()=>openFinalPriceEditor(lead,sale));
 root.querySelector('#reopen-sale')?.addEventListener('click',()=>openReopenSale(lead,sale));
 root.querySelectorAll('[data-activity]').forEach(b=>b.onclick=()=>openActivity(lead,b.dataset.activity));
 root.querySelector('#close-value')?.addEventListener('click',()=>changeStage(lead,'won'));
 root.querySelector('#add-followup')?.addEventListener('click',()=>openFollowup(lead));
 root.querySelector('#edit-next-followup')?.addEventListener('click',()=>openFollowup(lead,tasks[0]));
 root.querySelector('#archive-lead')?.addEventListener('click',()=>archiveLead(lead));
 root.querySelector('#add-payment')?.addEventListener('click',()=>openPayment(sale));
 root.querySelector('#reassign')?.addEventListener('change',async e=>{const {error}=await sb.from('leads').update({owner_id:e.target.value}).eq('id',lead.id);if(error){notify(errText(error),true);e.target.value=lead.owner_id;}else{await loadApp();notify('Oportunidad y seguimientos reasignados.');await openDetail(lead.id);}});
 root.querySelectorAll('[data-payment]').forEach(b=>b.onclick=()=>changePayment(b.dataset.payment,b.dataset.status,lead.id));wireTasks(root);
}
function openPriceEditor(lead){
 modal('Editar precio estimado',`<p class="subtext">${esc(lead.company_name)} · este importe se usa para el pipeline. Si la oportunidad está ganada, el valor final de la venta se edita por separado.</p><div class="field"><label for="estimated-price">Precio estimado (USD)</label><input id="estimated-price" name="estimated_value" type="number" min="0" step="0.01" required value="${Number(lead.estimated_value||0)}"></div>`,{submitLabel:'Guardar precio',onSubmit:async f=>{const value=Number(f.get('estimated_value'));if(!Number.isFinite(value)||value<0)throw new Error('Ingresa un precio válido.');const {error}=await sb.from('leads').update({estimated_value:value}).eq('id',lead.id);if(error)throw error;await loadApp();notify('Precio estimado actualizado.');queueMicrotask(()=>openDetail(lead.id));}});
}
function openFinalPriceEditor(lead,sale){
 modal('Editar valor final',`<p class="subtext">${esc(lead.company_name)} · lo ya cobrado es ${money(sale.collected_amount)}. El saldo pendiente se actualizará al guardar.</p><div class="field"><label for="final-price">Valor final acordado (USD)</label><input id="final-price" name="total_value" type="number" min="${Math.max(0.01,Number(sale.collected_amount||0))}" step="0.01" required value="${Number(sale.total_value)}"></div>`,{submitLabel:'Guardar valor final',onSubmit:async f=>{const value=Number(f.get('total_value'));if(!Number.isFinite(value)||value<=0||value<Number(sale.collected_amount))throw new Error('El valor final debe ser positivo y no menor a lo cobrado.');const {error}=await sb.from('sales').update({total_value:value}).eq('id',sale.id);if(error)throw error;await loadApp();notify('Valor final y saldo actualizados.');queueMicrotask(()=>openDetail(lead.id));}});
}
function openReopenSale(lead,sale){modal('Reabrir venta',`<div class="alert"><b>${esc(lead.company_name)}</b><p>La venta se eliminará y la oportunidad volverá a Negociación. Si existen cobros o pagos de comisión activos, primero debes anularlos.</p></div><div class="field"><label>Motivo de reapertura</label><textarea name="reason" minlength="3" maxlength="1000" required></textarea></div><label class="check-row"><input name="confirm" type="checkbox" required> Confirmo que deseo reabrir esta venta</label>`,{submitLabel:'Reabrir venta',onSubmit:async f=>{const {error}=await sb.request(`/api/admin/sales/${encodeURIComponent(sale.id)}/reopen`,{method:'POST',body:JSON.stringify({reason:String(f.get('reason')).trim(),confirm:f.get('confirm')==='on'})});if(error)throw error;await loadApp();notify('Venta reabierta. La oportunidad volvió a Negociación.');queueMicrotask(()=>openDetail(lead.id));}})}
function openEditLead(lead){
 const fields=[
  ['company_name','Empresa',lead.company_name,'text',true],
  ['contact_name','Contacto',lead.contact_name,'text',true],
  ['job_title','Cargo',lead.job_title,'text',false],
  ['phone','Teléfono',lead.phone,'tel',false],
  ['email','Email',lead.email,'email',false],
  ['website','Web',lead.website,'text',false]
 ];
 const input=([name,label,value,type,required])=>`<div class="field"><label for="edit-${name}">${label}</label><input id="edit-${name}" name="${name}" type="${type}" maxlength="160" ${required?'required minlength="2"':''} value="${esc(value||'')}"></div>`;
 modal('Editar información',`<div class="form-grid">${fields.map(input).join('')}<div class="field"><label for="edit-service">Servicio</label><select id="edit-service" name="service_id">${optionsServices(lead.service_id)}</select></div><div class="field"><label for="edit-source">Fuente</label><select id="edit-source" name="source">${[...new Set([...sources,lead.source].filter(Boolean))].map(x=>`<option ${x===lead.source?'selected':''}>${esc(x)}</option>`).join('')}</select></div><div class="field"><label for="edit-estimated-value">Precio estimado (USD)</label><input id="edit-estimated-value" name="estimated_value" type="number" min="0" step="0.01" required value="${Number(lead.estimated_value||0)}"></div></div><details><summary>Otros datos</summary><div class="form-grid">${[['city','Ciudad'],['country','País']].map(([name,label])=>`<div class="field"><label for="edit-${name}">${label}</label><input id="edit-${name}" name="${name}" maxlength="160" value="${esc(lead[name]||'')}"></div>`).join('')}<div class="field span-2"><label for="edit-notes">Notas</label><textarea id="edit-notes" name="notes" maxlength="4000">${esc(lead.notes||'')}</textarea></div></div></details>`,{wide:true,onSubmit:async f=>{
  const patch=Object.fromEntries(['company_name','contact_name','phone','email','job_title','website','city','country','source','notes'].map(k=>[k,String(f.get(k)||'').trim()||null]));
  patch.service_id=f.get('service_id')||null;
  patch.estimated_value=Number(f.get('estimated_value'));
  const {error}=await sb.from('leads').update(patch).eq('id',lead.id);
  if(error)throw error;
  await loadApp();notify('Información de la oportunidad actualizada.');queueMicrotask(()=>openDetail(lead.id));
 }});
}
async function changeStage(lead,status){
 const existing=sales.find(s=>s.lead_id===lead.id);
 if(status==='won'&&!existing){modal('Marcar oportunidad ganada',`<p class="notice">Registrar la venta no registra un cobro. Los cobros confirmados actualizarán el saldo.</p><div class="field"><label>Valor final acordado (USD)</label><input name="final_value" type="number" min="0.01" step="0.01" value="${Number(lead.estimated_value||0)}" required></div>`,{onSubmit:async f=>{await saveStage(lead,status,{final_value:Number(f.get('final_value'))});}});return;}
 if(status==='lost'){modal('Marcar oportunidad perdida',`<div class="field"><label>Motivo de pérdida</label><input name="reason" maxlength="500" required value="${esc(lead.loss_reason||'')}"></div>`,{onSubmit:async f=>saveStage(lead,status,{loss_reason:String(f.get('reason')).trim()})});return;}
 try{await saveStage(lead,status);}catch(e){notify(errText(e),true);await loadApp();}
}
function openActivity(lead,type='note'){
 modal(`Registrar ${activityLabel(type).toLowerCase()}`,`<div class="field"><label>Tipo de actividad</label><select name="type">${activityTypes.map(([key,label])=>`<option value="${key}" ${key===type?'selected':''}>${label}</option>`).join('')}</select></div><div class="field"><label>Asunto</label><input name="subject" maxlength="200" required placeholder="¿Qué hiciste con este cliente?"></div><div class="field"><label>Detalle opcional</label><textarea name="body" maxlength="4000"></textarea></div>`,{onSubmit:async f=>{const {error}=await sb.from('activities').insert({lead_id:lead.id,type:f.get('type'),subject:String(f.get('subject')).trim(),body:String(f.get('body')||'').trim()||null});if(error)throw error;await loadApp();notify('Actividad registrada.');queueMicrotask(()=>openDetail(lead.id));}});
}
function openPayment(sale){
 const requestKey=crypto.randomUUID();
 modal('Registrar cobro',`<div class="notice">Saldo ${money(sale.pending_balance)}.</div><div class="field"><label>Monto (USD)</label><input name="amount" type="number" min="0.01" step="0.01" max="${sale.pending_balance}" required></div><div class="field"><label>Fecha del pago (Ecuador)</label><input name="paid_at" type="date" value="${ecuadorDay(new Date())}" required></div><div class="field"><label>Estado</label><select name="status"><option value="confirmed">Confirmado: dinero recibido</option><option value="pending">Pendiente de confirmar</option></select></div><div class="field"><label>Método</label><select name="payment_method"><option>Transferencia</option><option>Tarjeta</option><option>Efectivo</option><option>PayPal</option><option>Otro</option></select></div><details><summary>Referencia y notas</summary><div class="field"><label>Referencia</label><input name="reference" maxlength="160"></div><div class="field"><label>Notas</label><textarea name="notes" maxlength="2000"></textarea></div></details>`,{onSubmit:async f=>{const {error}=await sb.from('payments').insert({sale_id:sale.id,amount:Number(f.get('amount')),paid_at:f.get('paid_at'),payment_method:f.get('payment_method'),status:f.get('status'),reference:String(f.get('reference')||'').trim()||null,notes:String(f.get('notes')||'').trim()||null,request_key:requestKey});if(error)throw error;await loadApp();notify('Cobro registrado. Saldo actualizado.');queueMicrotask(()=>openDetail(sale.lead_id));}});
}
function openOwnPasswordChange(){modal('Cambiar mi contraseña',`<div class="field"><label>Contraseña actual</label><input name="current_password" type="password" autocomplete="current-password" required></div><div class="field"><label>Nueva contraseña</label><input name="new_password" type="password" minlength="12" autocomplete="new-password" required><small>Mínimo 12 caracteres.</small></div>`,{submitLabel:'Cambiar contraseña',onSubmit:async f=>{const {error}=await sb.request('/api/auth/password',{method:'POST',body:JSON.stringify({current_password:f.get('current_password'),new_password:f.get('new_password')})});if(error)throw error;notify('Tu contraseña fue actualizada.');}})}
async function archiveLead(lead){try{const {error}=await sb.from('leads').update({deleted_at:new Date().toISOString()}).eq('id',lead.id);if(error)throw error;await loadApp();notify('Oportunidad archivada.')}catch(e){notify(errText(e),true)}}
function openService(){modal('Agregar servicio',`<div class="field"><label>Nombre del servicio *</label><input name="name" required maxlength="120"></div><div class="field"><label>Precio referencial (USD)</label><input name="default_price" type="number" min="0" step="0.01" value="0"></div>`,{onSubmit:async f=>{const {error}=await sb.from('services').insert({name:String(f.get('name')).trim(),default_price:Number(f.get('default_price')||0)});if(error)throw error;await loadApp();notify('Servicio agregado.')}})}
function exportCsv(){const rows=visibleLeads();const cols=['Fecha','Empresa','Contacto','Teléfono','Email','Responsable','Estado','Servicio','Precio estimado','Valor final','Valor mostrado','Seguimiento','Fuente'];const data=rows.map(l=>{const sale=leadSale(l);return [date(l.created_at),l.company_name,l.contact_name,l.phone,l.email,l.profiles?.full_name||person(l.owner_id),labelStage(l.status),l.services?.name,l.estimated_value,sale?.total_value??'',leadDisplayValue(l),l.next_action_at?date(l.next_action_at):'',l.source]});const csv=[cols,...data].map(r=>r.map(v=>`"${String(v??'').replace(/^[=+@\-\t\r]/,"'$&").replace(/"/g,'""')}"`).join(',')).join('\r\n');const link=document.createElement('a');link.href=URL.createObjectURL(new Blob(['\ufeff'+csv],{type:'text/csv;charset=utf-8'}));link.download='nextwebec-oportunidades.csv';link.click();URL.revokeObjectURL(link.href)}

const activityLabel=type=>activityTypes.find(x=>x[0]===type)?.[1]||({payment:'Cobro'}[type])||type;
const idleDays=lead=>Math.max(0,Math.floor((Date.now()-Date.parse(lead.last_contact_at||lead.created_at))/86400000));
function attentionRow(lead){return `<button class="attention-row" data-open="${lead.id}"><b>${esc(lead.company_name)}</b><span>${esc(lead.contact_name)} · ${idleDays(lead)>=14?'14+':idleDays(lead)>=7?'7+':idleDays(lead)} días sin actividad</span></button>`;}
function taskRow(task){const lead=leads.find(l=>l.id===task.lead_id)||archivedLeads.find(l=>l.id===task.lead_id);return `<div class="task-row"><button class="task-open" data-open="${task.lead_id}"><b>${esc(lead?.company_name||'Oportunidad')}</b><span>${esc(task.description)}</span><small>${dt(task.due_at)} · ${esc(followupTypes.find(x=>x[0]===task.type)?.[1]||'Otro')}${isAdmin()?' · '+esc(person(task.owner_id)):''}</small></button><div class="task-actions"><button class="btn small" data-complete="${task.id}">Completar</button><button class="btn small" data-postpone="${task.id}" data-days="1">Mañana</button><button class="btn small" data-postpone="${task.id}" data-days="3">En 3 días</button><button class="btn small" data-edit-task="${task.id}">Editar</button><button class="btn danger small" data-cancel-task="${task.id}">Anular</button></div></div>`;}
function wireTasks(root=document){root.querySelectorAll('[data-open]').forEach(b=>b.onclick=()=>openDetail(b.dataset.open));root.querySelectorAll('[data-complete]').forEach(b=>b.onclick=()=>finishTask(b.dataset.complete,'completed'));root.querySelectorAll('[data-postpone]').forEach(b=>b.onclick=()=>postponeTask(b.dataset.postpone,Number(b.dataset.days)));root.querySelectorAll('[data-cancel-task]').forEach(b=>b.onclick=()=>finishTask(b.dataset.cancelTask,'cancelled'));root.querySelectorAll('[data-edit-task]').forEach(b=>b.onclick=()=>{const task=followups.find(f=>f.id===b.dataset.editTask);openFollowup(leads.find(l=>l.id===task.lead_id),task);});}
async function postponeTask(id,days){const task=followups.find(f=>f.id===id),target=new Date(Date.now()+days*86400000),due=fromEcuadorInput(`${ecuadorDay(target)}T09:00`);try{const {error}=await sb.from('followups').update({due_at:due}).eq('id',id);if(error)throw error;const inDetail=Boolean(document.querySelector('.modal-backdrop'));await loadApp();notify(days===1?'Seguimiento movido a mañana a las 09:00.':`Seguimiento movido ${days} días a las 09:00.`);if(inDetail)await openDetail(task.lead_id);}catch(e){notify(errText(e),true);}}
async function finishTask(id,status){const task=followups.find(f=>f.id===id);try{const {error}=await sb.from('followups').update({status}).eq('id',id);if(error)throw error;const inDetail=Boolean(document.querySelector('.modal-backdrop'));await loadApp();notify(status==='completed'?'Seguimiento completado y registrado como actividad.':'Seguimiento cancelado.');if(inDetail)await openDetail(task.lead_id);}catch(e){notify(errText(e),true);}}
function chooseFollowup(){const active=leads.filter(l=>!l.deleted_at&&l.status!=='lost');if(!active.length){notify('Crea una oportunidad activa para programar un seguimiento.');return;}const root=modal('Elegir oportunidad',`<div class="field"><label>Oportunidad</label><select id="choose-lead">${active.map(l=>`<option value="${l.id}">${esc(l.company_name)} · ${esc(l.contact_name)}</option>`).join('')}</select></div><button class="btn primary" type="button" id="continue-followup">Continuar</button>`);root.querySelector('#continue-followup').onclick=()=>openFollowup(active.find(l=>l.id===root.querySelector('#choose-lead').value));}
function openFollowup(lead,task=null){modal(task?'Editar seguimiento':'Crear seguimiento',`<p class="subtext">${esc(lead.company_name)} · horario de Ecuador</p><div class="field"><label>Tipo</label><select name="type">${followupTypes.map(([key,label])=>`<option value="${key}" ${key===task?.type?'selected':''}>${label}</option>`).join('')}</select></div><div class="field"><label>Fecha y hora (Ecuador)</label><input name="due_at" type="datetime-local" required value="${ecuadorInput(task?.due_at)}"></div><div class="field"><label>¿Qué tienes que hacer?</label><input name="description" maxlength="1000" required value="${esc(task?.description||'')}" placeholder="Llamar a Stephanie para revisar la propuesta"></div>`,{onSubmit:async f=>{const body={type:f.get('type'),due_at:fromEcuadorInput(f.get('due_at')),description:String(f.get('description')).trim()};const query=task?sb.from('followups').update(body).eq('id',task.id):sb.from('followups').insert({...body,lead_id:lead.id});const {error}=await query;if(error)throw error;await loadApp();notify('Seguimiento guardado en la oportunidad, Mi día y Seguimientos.');queueMicrotask(()=>openDetail(lead.id));}});}
async function saveStage(lead,status,extra={}){const {error}=await sb.from('leads').update({status,...extra}).eq('id',lead.id);if(error)throw error;const inDetail=Boolean(document.querySelector('.modal-backdrop'));await loadApp();notify(`Estado actualizado: ${labelStage(status)}.`);if(inDetail)queueMicrotask(()=>openDetail(lead.id));}
async function changePayment(id,status,leadId){if(status==='cancelled'){openVoid('payments',id,()=>openDetail(leadId));return;}try{const {error}=await sb.from('payments').update({status}).eq('id',id);if(error)throw error;await loadApp();notify(status==='confirmed'?'Cobro confirmado. Saldo actualizado.':'Cobro cancelado. Saldo actualizado.');await openDetail(leadId);}catch(e){notify(errText(e),true);}}

async function financialReview(){const {data,error}=await sb.rpc('financial_review');if(error){notify(errText(error),true);return;}modal('Revisión de ventas',`<p class="notice">${data.sales.length} ventas registradas. ${data.possible_duplicates.length} coincidencias de empresa para revisar y ${data.inconsistencies.length} diferencias de cálculo y ${data.won_without_sale.length} oportunidades Ganadas sin valor final. No se ha eliminado ni corregido ningún dato.</p><div class="table-wrap"><table class="data-table audit-table"><thead><tr><th>Empresa</th><th>Estado</th><th>Valor final</th><th>Cobrado</th><th>Saldo</th></tr></thead><tbody>${data.sales.map(r=>`<tr><td>${esc(r.company_name)}${r.deleted_at?' (archivada)':''}</td><td>${esc(labelStage(r.status))}</td><td>${money(r.total_value)}</td><td>${money(r.confirmed_total)}</td><td>${money(r.pending_balance)}</td></tr>`).join('')}</tbody></table></div>${data.possible_duplicates.map(d=>`<p>${esc(d.company)}: ${d.count} oportunidades · ${esc(d.match_reason)}.</p>`).join('')}${data.inconsistencies.length?`<p class="alert">Hay cifras históricas inconsistentes. Revisa los cobros antes de modificarlos.</p>`:''}`,{wide:true});}
function editService(id){const service=services.find(s=>s.id===id);modal('Editar servicio',`<div class="field"><label>Nombre</label><input name="name" maxlength="120" required value="${esc(service.name)}"></div><div class="field"><label>Precio sugerido (USD)</label><input name="price" type="number" min="0" step="0.01" required value="${service.default_price}"></div>`,{onSubmit:async f=>{const {error}=await sb.from('services').update({name:String(f.get('name')).trim(),default_price:Number(f.get('price'))}).eq('id',id);if(error)throw error;await loadApp();notify('Servicio actualizado.');}});}
async function toggleService(id,active){try{const {error}=await sb.from('services').update({is_active:!active}).eq('id',id);if(error)throw error;await loadApp();notify(active?'Servicio desactivado.':'Servicio activado.');}catch(e){notify(errText(e),true);}}

const refreshTimer=setInterval(()=>{if(session&&!document.hidden&&!document.querySelector('.modal-backdrop')&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement?.tagName))loadApp();},45000);
refreshTimer.unref?.();
document.addEventListener('visibilitychange',()=>{if(session&&!document.hidden&&!document.querySelector('.modal-backdrop'))loadApp();});

async function deleteArchived(lead){
 if(!isAdmin()||!lead)return;
 const {data:preview,error}=await sb.request(`/api/admin/leads/${encodeURIComponent(lead.id)}/deletion-preview`);if(error){notify(errText(error),true);return;}
 modal('Eliminar oportunidad archivada',`<div class="alert"><b>Eliminar ${esc(lead.company_name)}</b><p>ID: ${esc(preview.lead.id)}. Venta: ${money(preview.sale?.total_value)}. Cobros: ${preview.payments.length}. Esta acción elimina la oportunidad y sus relaciones operativas. El historial financiero anulado queda conservado fuera de reportes.</p><p>${preview.can_delete?'No hay movimientos activos.':'Eliminación bloqueada: revisa los movimientos activos desde el detalle.'} Antes de eliminar se guarda y verifica un respaldo.</p></div><div class="field"><label>Escribe el nombre de la empresa para confirmar</label><input name="confirm_name" required autocomplete="off" placeholder="${esc(lead.company_name)}"></div>`,{submitLabel:'Eliminar definitivamente',onSubmit:async f=>{
 const name=String(f.get('confirm_name')||'').trim();if(name!==lead.company_name)throw new Error('El nombre no coincide.');
 const response=await fetch(`/api/admin/leads/${encodeURIComponent(lead.id)}`,{method:'DELETE',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify({confirm_name:name})});const result=await response.json();if(!response.ok||result.error)throw new Error(result.error?.message||'No se pudo eliminar.');
 await loadApp();notify('Oportunidad eliminada. Totales actualizados.');
 }});
}

function openVoid(kind,id,after){modal('Confirmar anulación',`<p class="notice">Esta operación revierte el efecto financiero y conserva el historial.</p><div class="field"><label>Motivo obligatorio</label><textarea name="reason" required minlength="3" maxlength="1000"></textarea></div><label><input name="confirm" type="checkbox" required> Confirmo la anulación de este movimiento</label>`,{onSubmit:async f=>{const {error}=await sb.request(`/api/admin/${kind}/${encodeURIComponent(id)}/void`,{method:'POST',body:JSON.stringify({reason:f.get('reason'),confirm:f.get('confirm')==='on'})});if(error)throw error;await loadApp();notify('Movimiento anulado. Indicadores actualizados.');queueMicrotask(after);}});}

const projectStatuses=[['pending_content','Pendiente de contenido'],['planning','Planificación'],['design','Diseño'],['development','Desarrollo'],['internal_review','Revisión interna'],['client_review','Revisión del cliente'],['corrections','Correcciones'],['approved','Aprobado'],['publication','Publicación'],['delivered','Entregado']];
const quoteStatuses={draft:'Borrador',sent:'Enviada',accepted:'Aceptada',rejected:'Rechazada'};
function renderClients(){
 const clients=platformData.clients;
 setView(`<div class="page-head"><div><h1>Clientes</h1><p>Fichas de clientes, oportunidades, ventas y proyectos.</p></div><div class="table-actions">${isAdmin()?'<button class="btn primary" id="create-client">＋ Crear cliente</button>':''}<button class="btn" id="convert-client">Vincular oportunidad</button></div></div><section class="panel"><div class="table-wrap"><table class="data-table"><thead><tr><th>Cliente</th><th>Responsable</th><th>Contratado</th><th>Cobrado</th><th>Saldo</th><th></th></tr></thead><tbody>${clients.map(c=>`<tr><td><b>${esc(c.display_name)}</b><small class="subtext">${esc(c.tax_id||c.email||'')}</small></td><td>${esc(person(c.owner_id))}</td><td>${money(c.contracted_cents/100)}</td><td>${money(c.collected_cents/100)}</td><td>${money((c.contracted_cents-c.collected_cents)/100)}</td><td><button class="btn small" data-client="${c.id}">Ver ficha</button></td></tr>`).join('')}</tbody></table></div><div class="mobile-cards">${clients.map(c=>`<article class="mobile-lead"><h3>${esc(c.display_name)}</h3><p>Contratado ${money(c.contracted_cents/100)} · Cobrado ${money(c.collected_cents/100)}</p><button class="btn small" data-client="${c.id}">Ver ficha</button></article>`).join('')}</div>${clients.length?'':'<div class="empty"><strong>Aún no hay clientes</strong>Crea una ficha o vincula una oportunidad.</div>'}</section>`);
 document.querySelector('#create-client')?.addEventListener('click',openCreateClient);
 document.querySelector('#convert-client').onclick=openClientConversion;
 document.querySelectorAll('[data-client]').forEach(b=>b.onclick=()=>openClient(b.dataset.client));
}
function openCreateClient(){
 modal('Crear cliente',`<div class="field"><label>Nombre del cliente *</label><input name="display_name" required minlength="2" maxlength="160" autofocus></div><div class="field"><label>Razón social (opcional)</label><input name="legal_name" maxlength="160"></div><div class="field"><label>Identificación / RUC (opcional)</label><input name="tax_id" maxlength="32"></div><div class="field"><label>Correo (opcional)</label><input name="email" type="email" maxlength="254"></div><div class="field"><label>Teléfono (opcional)</label><input name="phone" type="tel" maxlength="40"></div>`,{submitLabel:'Crear cliente',onSubmit:async f=>{const body=Object.fromEntries(f);const {data,error}=await sb.request('/api/platform/clients',{method:'POST',body:JSON.stringify(body)});if(error)throw error;await loadApp();notify('Cliente creado.');queueMicrotask(()=>openClient(data.id));}});
}
function openClientConversion(){
 const candidates=leads.filter(l=>!l.deleted_at&&!platformData.links.some(link=>link.lead_id===l.id));
 if(!candidates.length){notify('Todas las oportunidades visibles ya tienen ficha de cliente.');return;}
 modal('Vincular oportunidad a cliente',`<p class="notice">Si el cliente ya existe, selecciónalo. El CRM no creará otra ficha.</p><div class="field"><label>Oportunidad</label><select name="lead_id">${candidates.map(l=>`<option value="${l.id}">${esc(l.company_name)} · ${esc(l.contact_name)}</option>`).join('')}</select></div><div class="field"><label>Cliente existente</label><select name="client_id"><option value="">Crear ficha nueva</option>${platformData.clients.map(c=>`<option value="${c.id}">${esc(c.display_name)}</option>`).join('')}</select></div><div class="field"><label>Identificación / RUC para ficha nueva</label><input name="tax_id" maxlength="32"></div><div class="field"><label>Razón social para ficha nueva (opcional)</label><input name="legal_name" maxlength="160"></div>`,{submitLabel:'Vincular cliente',onSubmit:async f=>{const body=Object.fromEntries(f);const {data,error}=await sb.request('/api/platform/clients/from-lead',{method:'POST',body:JSON.stringify(body)});if(error)throw error;await loadApp();notify('Ficha de cliente vinculada.');queueMicrotask(()=>openClient(data.id));}});
}
async function openClient(id){
 const {data,error}=await sb.request(`/api/platform/clients/${encodeURIComponent(id)}`);if(error){notify(errText(error),true);return;}
 const c=data.client;
 const root=modal('Ficha de cliente',`<div class="detail-grid"><div><h3 class="detail-title">${esc(c.display_name)}</h3><p class="subtext">${esc(c.legal_name)} ${c.tax_id?'· '+esc(c.tax_id):''}</p><p>${esc(c.email||'Sin correo')} · ${esc(c.phone||'Sin teléfono')}</p></div><div class="detail-facts"><div class="fact"><label>Oportunidades</label><b>${data.leads.length}</b></div><div class="fact"><label>Ventas</label><b>${data.sales.length}</b></div><div class="fact"><label>Cotizaciones</label><b>${data.quotes.length}</b></div><div class="fact"><label>Proyectos</label><b>${data.projects.length}</b></div></div></div><div class="quick-actions"><button class="btn primary" id="client-new-quote">Nueva cotización</button></div><h3>Ventas y cobros</h3>${data.sales.map(s=>`<div class="payment-row"><span>${esc(data.leads.find(l=>l.id===s.lead_id)?.company_name||'Venta')}</span><b>${money(s.total_value)} contratado · ${money(s.collected_amount)} cobrado · ${money(s.pending_balance)} pendiente</b></div>`).join('')||'<p class="subtext">Sin ventas todavía.</p>'}<h3>Cotizaciones</h3>${data.quotes.map(q=>`<div class="payment-row"><span>${esc(q.number)} · ${esc(quoteStatuses[q.status])}</span><button class="btn small" data-quote="${q.id}">Ver</button></div>`).join('')||'<p class="subtext">Sin cotizaciones.</p>'}`,{wide:true});
 root.querySelector('#client-new-quote').onclick=()=>openQuoteForm(id);
 root.querySelectorAll('[data-quote]').forEach(b=>b.onclick=()=>openQuote(b.dataset.quote));
}
function renderQuotes(){
 const rows=platformData.quotes;
 setView(`<div class="page-head"><div><h1>Cotizaciones</h1><p>Conceptos editables, vigencia, anticipo y PDF generado en el servidor.</p></div><button class="btn primary" id="new-quote">Nueva cotización</button></div><section class="panel"><div class="table-wrap"><table class="data-table"><thead><tr><th>Número</th><th>Cliente</th><th>Estado</th><th>Total</th><th>Fecha</th><th></th></tr></thead><tbody>${rows.map(q=>`<tr><td><b>${esc(q.number)}</b></td><td>${esc(q.client_name)}</td><td>${esc(quoteStatuses[q.status])}</td><td>${money(q.total_cents/100)}</td><td>${date(q.created_at)}</td><td><button class="btn small" data-quote="${q.id}">Ver</button></td></tr>`).join('')}</tbody></table></div><div class="mobile-cards">${rows.map(q=>`<article class="mobile-lead"><h3>${esc(q.number)} · ${esc(q.client_name)}</h3><p>${esc(quoteStatuses[q.status])} · ${money(q.total_cents/100)}</p><button class="btn small" data-quote="${q.id}">Ver</button></article>`).join('')}</div>${rows.length?'':'<div class="empty"><strong>Sin cotizaciones</strong>Crea una desde la ficha de un cliente.</div>'}</section>`);
 document.querySelector('#new-quote').onclick=()=>openQuoteForm();
 document.querySelectorAll('[data-quote]').forEach(b=>b.onclick=()=>openQuote(b.dataset.quote));
}
function openQuoteForm(clientId=null){
 if(!platformData.clients.length){notify('Crea primero una ficha de cliente.');return;}
 const selected=clientId||platformData.clients[0].id;
 const row=(description='',price='0')=>`<div class="quote-item"><input name="description" aria-label="Concepto" placeholder="Servicio o concepto" required maxlength="250" value="${esc(description)}"><input name="quantity" aria-label="Cantidad" type="number" min="1" max="10000" value="1" required><input name="unit_price" aria-label="Precio unitario USD" type="number" min="0" step="0.01" value="${esc(price)}" required><button class="btn small" type="button" data-remove-item aria-label="Quitar concepto">Quitar</button></div>`;
 const root=modal('Nueva cotización',`<div class="form-grid"><div class="field"><label>Cliente</label><select name="client_id" id="quote-client">${platformData.clients.map(c=>`<option value="${c.id}" ${c.id===selected?'selected':''}>${esc(c.display_name)}</option>`).join('')}</select></div><div class="field"><label>Oportunidad</label><select name="lead_id" id="quote-lead"></select></div></div><div class="field"><label>Agregar del catálogo</label><div class="quote-add"><select id="quote-service"><option value="">Servicio personalizado</option>${services.filter(s=>s.is_active).map(s=>`<option value="${s.id}">${esc(s.name)} · ${money(s.default_price)}</option>`).join('')}</select><button class="btn" type="button" id="add-quote-item">Agregar concepto</button></div></div><div class="quote-items" id="quote-items">${row()}</div><div class="form-grid"><div class="field"><label>Descuento USD</label><input name="discount" type="number" min="0" step="0.01" value="0"></div><div class="field"><label>Impuesto %</label><input name="tax_percent" type="number" min="0" max="100" step="0.01" value="0"></div><div class="field"><label>Anticipo USD</label><input name="deposit" type="number" min="0" step="0.01" value="0"></div><div class="field"><label>Válida hasta</label><input name="valid_until" type="date"></div></div><div class="field"><label>Condiciones</label><textarea name="terms" maxlength="2000"></textarea></div><div class="field"><label>Observaciones</label><textarea name="notes" maxlength="2000"></textarea></div>`,{wide:true,submitLabel:'Crear borrador',onSubmit:async f=>{
   const descriptions=f.getAll('description'),quantities=f.getAll('quantity'),prices=f.getAll('unit_price');
   const taxPercent=Number(f.get('tax_percent'));if(!Number.isFinite(taxPercent)||taxPercent<0||taxPercent>100)throw new Error('Impuesto inválido.');
   const body={client_id:f.get('client_id'),lead_id:f.get('lead_id')||null,items:descriptions.map((description,i)=>({description,quantity:Number(quantities[i]),unit_price:prices[i]})),discount:f.get('discount'),tax_rate_bps:Math.round(taxPercent*100),deposit:f.get('deposit'),valid_until:f.get('valid_until')||null,terms:f.get('terms'),notes:f.get('notes')};
   const {data,error}=await sb.request('/api/platform/quotes',{method:'POST',body:JSON.stringify(body)});if(error)throw error;await loadApp();notify('Cotización guardada.');queueMicrotask(()=>openQuote(data.id));
 }});
 const updateLeads=()=>{const cid=root.querySelector('#quote-client').value;const ids=platformData.links.filter(x=>x.client_id===cid).map(x=>x.lead_id);root.querySelector('#quote-lead').innerHTML=`${leads.filter(l=>ids.includes(l.id)).map(l=>`<option value="${l.id}">${esc(l.company_name)}</option>`).join('')}${isAdmin()?'<option value="">Sin oportunidad</option>':''}`;};
 root.querySelector('#quote-client').onchange=updateLeads;updateLeads();
 root.querySelector('#add-quote-item').onclick=()=>{const service=services.find(s=>s.id===root.querySelector('#quote-service').value);root.querySelector('#quote-items').insertAdjacentHTML('beforeend',row(service?.name||'',service?.default_price??'0'));};
 root.querySelector('#quote-items').onclick=e=>{if(e.target.matches('[data-remove-item]')&&root.querySelectorAll('.quote-item').length>1)e.target.closest('.quote-item').remove();};
}
async function openQuote(id){
 const {data:q,error}=await sb.request(`/api/platform/quotes/${encodeURIComponent(id)}`);if(error){notify(errText(error),true);return;}
 const root=modal('Cotización '+esc(q.number),`<p class="notice">Estado: ${esc(quoteStatuses[q.status])} · ${date(q.created_at)}${q.valid_until?' · válida hasta '+date(q.valid_until):''}</p><div class="table-wrap"><table class="data-table quote-table"><thead><tr><th>Concepto</th><th>Cantidad</th><th>Precio</th><th>Total</th></tr></thead><tbody>${q.items.map(item=>`<tr><td>${esc(item.description)}</td><td>${item.quantity}</td><td>${money(item.unit_price_cents/100)}</td><td>${money(item.quantity*item.unit_price_cents/100)}</td></tr>`).join('')}</tbody></table></div><div class="quote-totals"><span>Subtotal ${money(q.subtotal_cents/100)}</span><span>Descuento ${money(q.discount_cents/100)}</span><span>Impuestos ${money(q.tax_cents/100)}</span><strong>Total ${money(q.total_cents/100)}</strong><span>Anticipo propuesto ${money(q.deposit_cents/100)}</span></div><p class="subtext">${esc(q.terms||'Sin condiciones adicionales.')}</p><div class="quick-actions"><a class="btn" href="/api/platform/quotes/${encodeURIComponent(id)}/pdf" target="_blank" rel="noopener">Descargar PDF</a>${q.status==='draft'?'<button class="btn primary" data-quote-status="sent">Marcar enviada</button>':''}${q.status==='sent'?'<button class="btn primary" data-quote-status="accepted">Registrar aceptación</button><button class="btn" data-quote-status="rejected">Registrar rechazo</button>':''}${q.status==='accepted'&&q.lead_id?(sales.some(s=>s.lead_id===q.lead_id)?'<span class="notice">Venta registrada</span>':'<button class="btn primary" id="convert-quote">Convertir en venta</button>'):''}</div>`,{wide:true});
 root.querySelectorAll('[data-quote-status]').forEach(b=>b.onclick=async()=>{const {error}=await sb.request(`/api/platform/quotes/${encodeURIComponent(id)}/status`,{method:'POST',body:JSON.stringify({status:b.dataset.quoteStatus})});if(error){notify(errText(error),true);return;}await loadApp();queueMicrotask(()=>openQuote(id));});
 root.querySelector('#convert-quote')?.addEventListener('click',async()=>{const {error}=await sb.request(`/api/platform/quotes/${encodeURIComponent(id)}/convert`,{method:'POST',body:'{}'});if(error){notify(errText(error),true);return;}await loadApp();notify('Venta registrada; el proyecto se creará al confirmar el anticipo.');queueMicrotask(()=>openQuote(id));});
}
function renderProjects(){
 const rows=platformData.projects;
 setView(`<div class="page-head"><div><h1>Proyectos</h1><p>Se crean al confirmar un cobro de la venta.</p></div></div><section class="panel"><div class="table-wrap"><table class="data-table"><thead><tr><th>Proyecto</th><th>Estado</th><th>Contratado</th><th>Cobrado</th><th>Saldo</th><th>Actualizado</th><th></th></tr></thead><tbody>${rows.map(p=>`<tr><td><b>${esc(p.project_name||p.company_name)}</b><small class="subtext">${esc(p.company_name)}</small></td><td>${isAdmin()?`<select data-project-status="${p.id}">${projectStatuses.map(([key,label])=>`<option value="${key}" ${p.status===key?'selected':''}>${label}</option>`).join('')}</select>`:esc(projectStatuses.find(s=>s[0]===p.status)?.[1]||p.status)}</td><td>${money(p.total_value)}</td><td>${money(p.collected_amount)}</td><td>${money(p.pending_balance)}</td><td>${date(p.updated_at)}</td><td><button class="btn small" data-project-tasks="${p.id}">Tareas</button></td></tr>`).join('')}</tbody></table></div><div class="mobile-cards">${rows.map(p=>`<article class="mobile-lead"><h3>${esc(p.project_name||p.company_name)}</h3><p>${esc(projectStatuses.find(s=>s[0]===p.status)?.[1]||p.status)} · Cobrado ${money(p.collected_amount)}</p>${isAdmin()?`<select data-project-status="${p.id}">${projectStatuses.map(([key,label])=>`<option value="${key}" ${p.status===key?'selected':''}>${label}</option>`).join('')}</select>`:''}<button class="btn small" data-project-tasks="${p.id}">Ver tareas</button></article>`).join('')}</div>${rows.length?'':'<div class="empty"><strong>Sin proyectos activos</strong>Al confirmar un anticipo, el proyecto aparecerá aquí.</div>'}</section>`);
 document.querySelectorAll('[data-project-status]').forEach(s=>s.onchange=async()=>{const {error}=await sb.request(`/api/platform/projects/${encodeURIComponent(s.dataset.projectStatus)}`,{method:'PATCH',body:JSON.stringify({status:s.value})});if(error){notify(errText(error),true);renderPage();return;}await loadApp();notify('Estado de proyecto actualizado.');});
 document.querySelectorAll('[data-project-tasks]').forEach(b=>b.onclick=()=>openProjectTasks(b.dataset.projectTasks));
}
async function openProjectTasks(projectId){
 const project=platformData.projects.find(p=>p.id===projectId);
 if(!project)return;
 const {data:tasks,error}=await sb.request(`/api/platform/projects/${encodeURIComponent(projectId)}/tasks`);
 if(error){notify(errText(error),true);return;}
 const labels={open:'Pendiente',in_progress:'En curso',done:'Completada',cancelled:'Cancelada'},priorities={low:'Baja',medium:'Media',high:'Alta',urgent:'Urgente'};
 const rows=tasks.map(t=>`<div class="payment-row"><span><b>${esc(t.title)}</b><small>${esc(priorities[t.priority])} · ${t.due_at?date(t.due_at):'Sin fecha límite'}${t.assignee_name?' · '+esc(t.assignee_name):''}${t.dependency_title?' · Depende de '+esc(t.dependency_title):''}</small>${t.description?`<small>${esc(t.description)}</small>`:''}</span>${isAdmin()?`<select data-project-task-status="${t.id}">${Object.entries(labels).map(([key,label])=>`<option value="${key}" ${t.status===key?'selected':''}>${label}</option>`).join('')}</select>`:`<b>${esc(labels[t.status])}</b>`}</div>`).join('')||'<p class="empty">Aún no hay tareas en este proyecto.</p>';
 const root=modal(`Tareas · ${esc(project.project_name||project.company_name)}`,`${isAdmin()?'<div class="quick-actions"><button class="btn primary" id="new-project-task">＋ Agregar tarea</button></div>':''}${rows}`,{wide:true});
 root.querySelector('#new-project-task')?.addEventListener('click',()=>openProjectTaskForm(project,tasks));
 root.querySelectorAll('[data-project-task-status]').forEach(select=>select.onchange=async()=>{const {error}=await sb.request(`/api/platform/project-tasks/${encodeURIComponent(select.dataset.projectTaskStatus)}`,{method:'PATCH',body:JSON.stringify({status:select.value})});if(error){notify(errText(error),true);queueMicrotask(()=>openProjectTasks(projectId));return;}notify('Tarea actualizada.');queueMicrotask(()=>openProjectTasks(projectId));});
}
function openProjectTaskForm(project,tasks){
 const dependencies=tasks.map(t=>`<option value="${t.id}">${esc(t.title)}</option>`).join('');
 const assignees=profiles.filter(p=>p.is_active).map(p=>`<option value="${p.id}">${esc(p.full_name)}</option>`).join('');
 modal('Nueva tarea de proyecto',`<div class="field"><label>Tarea</label><input name="title" required maxlength="160" autofocus></div><div class="field"><label>Descripción</label><textarea name="description" maxlength="2000"></textarea></div><div class="form-grid"><div class="field"><label>Prioridad</label><select name="priority"><option value="low">Baja</option><option value="medium" selected>Media</option><option value="high">Alta</option><option value="urgent">Urgente</option></select></div><div class="field"><label>Fecha límite</label><input name="due_at" type="date"></div></div><div class="field"><label>Responsable</label><select name="assignee_id"><option value="">Sin asignar</option>${assignees}</select></div><div class="field"><label>Depende de</label><select name="depends_on"><option value="">Sin dependencia</option>${dependencies}</select></div>`,{submitLabel:'Crear tarea',onSubmit:async form=>{const body=Object.fromEntries(form);const {error}=await sb.request(`/api/platform/projects/${encodeURIComponent(project.id)}/tasks`,{method:'POST',body:JSON.stringify(body)});if(error)throw error;notify('Tarea de proyecto creada.');queueMicrotask(()=>openProjectTasks(project.id));}});
}
